#include "stdafx.h"#include "TrendReaderImpl.h"KTrendReaderImpl::KTrendReaderImpl( HANDLE curPipeHandle, bool *pisStopClientService ): m_curPipeHandle( curPipeHandle ), m_pisStopClientService( pisStopClientService ){}BOOL KTrendReaderImpl::ReadData( PVOID lpBuffer, DWORD nNumberOfBytesToRead, LPDWORD lpNumberOfBytesRead ){  BOOL fSuccess = ReadFile( m_curPipeHandle, lpBuffer, nNumberOfBytesToRead, lpNumberOfBytesRead, NULL);  return fSuccess;}BOOL KTrendReaderImpl::WriteData( LPCVOID lpBuffer, DWORD nNumberOfBytesToWrite, LPDWORD lpNumberOfBytesWritten ){  BOOL fSuccess = WriteFile( m_curPipeHandle, lpBuffer, nNumberOfBytesToWrite, lpNumberOfBytesWritten, NULL );  FlushFileBuffers( m_curPipeHandle );  return fSuccess;}bool KTrendReaderImpl::IsStopClientService(){  if( !m_pisStopClientService )    return true;  return *m_pisStopClientService;}